-- Applied automatically (idempotently) by app/src/clothes/drying.ts at startup.
-- Clips, garments and sessions get UUID ids generated by PostgreSQL (people only choose names).
-- Databases created with text ids (c1, g_xxx, demo-s1) are converted once, keeping every link.
-- The clip that receives readings on clothes/raw is marked by clips.topic.
ALTER TABLE clips ADD COLUMN IF NOT EXISTS topic TEXT;

DO $$
DECLARE r record;
BEGIN
  IF (SELECT data_type FROM information_schema.columns WHERE table_name = 'clips' AND column_name = 'id') = 'text' THEN
    CREATE TEMP TABLE clip_ids ON COMMIT DROP AS SELECT id AS old_id, gen_random_uuid()::text AS new_id FROM clips;
    CREATE TEMP TABLE garment_ids ON COMMIT DROP AS SELECT id AS old_id, gen_random_uuid()::text AS new_id FROM garments;
    FOR r IN SELECT conname FROM pg_constraint WHERE conrelid = 'drying_sessions'::regclass AND contype = 'f' LOOP
      EXECUTE format('ALTER TABLE drying_sessions DROP CONSTRAINT %I', r.conname);
    END LOOP;
    UPDATE drying_sessions s SET clip_id = m.new_id FROM clip_ids m WHERE s.clip_id = m.old_id;
    UPDATE drying_sessions s SET garment_id = m.new_id FROM garment_ids m WHERE s.garment_id = m.old_id;
    UPDATE drying_sessions SET id = gen_random_uuid()::text;
    UPDATE clips SET topic = 'clothes/raw' WHERE id = 'c1' AND NOT is_demo AND topic IS NULL;
    UPDATE clips c SET id = m.new_id FROM clip_ids m WHERE c.id = m.old_id;
    UPDATE garments g SET id = m.new_id FROM garment_ids m WHERE g.id = m.old_id;
    ALTER TABLE clips ALTER COLUMN id TYPE uuid USING id::uuid, ALTER COLUMN id SET DEFAULT gen_random_uuid();
    ALTER TABLE garments ALTER COLUMN id TYPE uuid USING id::uuid, ALTER COLUMN id SET DEFAULT gen_random_uuid();
    ALTER TABLE drying_sessions
      ALTER COLUMN id TYPE uuid USING id::uuid, ALTER COLUMN id SET DEFAULT gen_random_uuid(),
      ALTER COLUMN clip_id TYPE uuid USING clip_id::uuid,
      ALTER COLUMN garment_id TYPE uuid USING garment_id::uuid;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'drying_sessions_clip_is_demo_fkey') THEN
    ALTER TABLE drying_sessions ADD CONSTRAINT drying_sessions_clip_is_demo_fkey
      FOREIGN KEY (clip_id, is_demo) REFERENCES clips (id, is_demo);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'drying_sessions_garment_is_demo_fkey') THEN
    ALTER TABLE drying_sessions ADD CONSTRAINT drying_sessions_garment_is_demo_fkey
      FOREIGN KEY (garment_id, is_demo) REFERENCES garments (id, is_demo);
  END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS clips_topic_key ON clips (topic) WHERE topic IS NOT NULL;
-- The real clip on clothes/raw (the app creates 衣夾-01 if none exists).
INSERT INTO clips (name, topic)
SELECT '衣夾-01', 'clothes/raw' WHERE NOT EXISTS (SELECT 1 FROM clips WHERE topic = 'clothes/raw');

-- Names repeat neither among real nor among demo rows (case and surrounding spaces ignored).
CREATE UNIQUE INDEX IF NOT EXISTS clips_name_key ON clips (lower(btrim(name)), is_demo);
CREATE UNIQUE INDEX IF NOT EXISTS garments_name_key ON garments (lower(btrim(name)), is_demo);
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'clips_name_trimmed') THEN
    ALTER TABLE clips ADD CONSTRAINT clips_name_trimmed CHECK (name = btrim(name)) NOT VALID;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'garments_name_trimmed') THEN
    ALTER TABLE garments ADD CONSTRAINT garments_name_trimmed CHECK (name = btrim(name)) NOT VALID;
  END IF;
END $$;
